// [4.16] Curso original y trazable: A03, diapositivas 1-36,
// más fundamentos de lectura de la carta con referencia ASHRAE/PsychroLib.
// Evitar reproducción literal extensa de material bibliográfico.
public sealed record TheoryTopic(
    string Id,string Group,int FirstSlide,int LastSlide,string Title,
    string Summary,string PhysicalExplanation,string ChartReading,
    string Equation,string Procedure,string Limits,string Source,string LessonKind)
{
    public string DisplayTitle => Group=="A03"
        ? $"A03 {FirstSlide}" + (FirstSlide==LastSlide?"":$"–{LastSlide}") + $" · {Title}"
        : $"Carta · {Title}";
    public string SlideLabel => Group=="A03"
        ? (FirstSlide==LastSlide?$"Diapositiva {FirstSlide}":$"Diapositivas {FirstSlide}–{LastSlide}")
        : "Fundamento complementario de la carta";
}

