        new TheoryTopic("BASE-01", "Carta", 0, 0, "Qué representa una carta psicrométrica", "Una carta reúne estados de aire húmedo a una presión absoluta especificada y permite estudiar transformaciones sin asignar potencias por sí sola.", "El aire seco y el vapor se modelan como mezcla; una propiedad de estado no equivale a la carga del equipo.", "Fijar P; localizar Tbs en el eje horizontal y W en el vertical; identificar la curva HR=100%.", "p_v=P·W/(0,621945+W); HR=100·p_v/p_ws(Tbs).", "1) Fijar presión absoluta. 2) Elegir dos propiedades independientes. 3) Encontrar su intersección. 4) Verificar HR≤100%. 5) Leer h, Tbh, Trocío y v.", "Una carta a una presión no puede reutilizarse sin recalcular a otra presión; fuera de saturación se requiere otra fase o modelo.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Heating"),
        new TheoryTopic("BASE-02", "Carta", 0, 0, "Ejes Tbs y W: cómo leer un punto", "Tbs es temperatura de bulbo seco; W es masa de vapor por masa de aire seco (kg/kgda o g/kgda).", "Calentar sin introducir vapor conserva W pero modifica HR. Enfriar a W constante se detiene en el rocío.", "Tbs aumenta hacia la derecha; W aumenta hacia arriba. Un punto se construye cruzando sus coordenadas.", "W=0,621945·p_v/(P−p_v); 1 kg/kgda=1000 g/kgda.", "Cambiar Tbs manteniendo W, observar horizontalidad y descenso de HR en calefacción.", "La etiqueta histórica «humedad absoluta» de la app describe razón de humedad por kgda, no humedad volumétrica kg/m³.", "PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Heating"),
        new TheoryTopic("BASE-03", "Carta", 0, 0, "Curva de saturación: HR=100%", "Límite entre aire húmedo monofásico y condición de saturación con vapor a la presión seleccionada.", "A saturación, p_v=p_ws(T); más enfriamiento suele producir condensado.", "Es la envolvente curva superior/izquierda del dominio psicrométrico ordinario.", "W_sat(T,P)=0,621945·p_ws(T)/(P−p_ws(T)).", "Comparar W real con W_sat a la misma T y P; no colocar puntos por encima de W_sat.", "No representa niebla, hielo ni balance bifásico de condensación; p_ws(T) debe ser inferior a P.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Cooling"),
        new TheoryTopic("BASE-04", "Carta", 0, 0, "Familia de humedad relativa HR", "Cada curva interior une estados con igual HR; no son líneas de cantidad de agua constante.", "Cuando T cambia con W fijo, cambia la presión de saturación y por tanto HR.", "Seguir una curva de HR constante hacia otras temperaturas, sin confundirla con W constante.", "HR=100·p_v/p_ws(Tbs); p_v=P·W/(0,621945+W).", "Evaluar dos estados en la misma P: uno calentado y otro enfriado manteniendo W.", "Una HR alta no significa necesariamente mayor masa de vapor que otra corriente más caliente.", "PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Heating"),
        new TheoryTopic("BASE-05", "Carta", 0, 0, "Bulbo húmedo y curvas Tbh", "Tbh caracteriza la saturación adiabática del aire; normalmente Trocío≤Tbh≤Tbs en estados ordinarios.", "La evaporación consume energía y enfría la corriente mientras W aumenta.", "Localizar Tbh en el límite saturado y seguir la familia de líneas inclinadas correspondiente.", "W=f(Tbs,Tbh,P); Tbh se obtiene resolviendo la ecuación psicrométrica.", "Comparar Tbs, Tbh y rocío antes/después de un lavador ideal.", "Tbh no es estrictamente la línea de entalpía constante; evite asumir igualdad perfecta.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Evaporative"),
        new TheoryTopic("BASE-06", "Carta", 0, 0, "Punto de rocío Trocío", "Temperatura a la que el vapor existente se encuentra saturado si se enfría manteniendo su presión parcial.", "Es el umbral de condensación por enfriamiento sensible de una mezcla.", "Desde un punto, trazar horizontalmente (W constante) hasta HR=100% y leer T.", "p_ws(Trocío)=p_v=P·W/(0,621945+W).", "1) Hallar W. 2) Hallar p_v. 3) Invertir p_ws. 4) Comparar Trocío con Tbs.", "Si W=0 exactamente, el rocío no está definido; no asignar cero grados.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Cooling"),
        new TheoryTopic("BASE-07", "Carta", 0, 0, "Isolíneas de entalpía h", "La entalpía específica del aire húmedo es una convención referida al kg de aire seco.", "Una diferencia de entalpía cuantifica energía por kgda; potencia requiere flujo másico.", "Identificar diagonales de entalpía; no confundir con Tbh, aunque estén próximas.", "h≈1,006·Tbs + W(2501+1,86·Tbs) kJ/kgda; Q̇=ṁda(h2−h1).", "Leer h1 y h2; obtener Δh; multiplicar por ṁda únicamente si existe el caudal.", "En serpentín húmedo el condensado retira energía adicional según su entalpía; no inventar t_cond.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Dehumidification"),
        new TheoryTopic("BASE-08", "Carta", 0, 0, "Volumen específico y caudal másico", "v es m³ de aire húmedo por kg de aire seco; depende de P, T y W.", "Dos corrientes con igual caudal volumétrico no necesariamente tienen igual masa de aire seco.", "Leer la familia de v constante; sus unidades cambian entre SI/IP.", "ṁda=V̇/v; v≈R_da·T_K·(1+1,607858·W)/P.", "Convertir m³/h a m³/s y dividir por v individual de cada corriente antes de mezclar.", "Un promedio de caudales volumétricos sin ajustar por v viola los balances de masa.", "PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Mixing"),
        new TheoryTopic("BASE-09", "Carta", 0, 0, "Factor de calor sensible FCS/SHR", "FCS compara la parte sensible con la energía total del sistema considerado.", "Sirve para orientar procesos de acondicionamiento, pero no determina un punto único sin cargas y caudal.", "El transportador auxiliar orienta la pendiente sensible/total; debe referirse al estado interior y a una convención.", "FCS=Q_sensible/Q_total (signos y límites coherentes).", "Calcular cargas sensible/latente; fijar estado del local; determinar también caudal o ΔT de impulsión.", "No confundir FCS, BF, Δh y entropía relativa; ninguna de estas variables es HR.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals", "SHR"),
        new TheoryTopic("BASE-10", "Carta", 0, 0, "Δh y entropía relativa s*: extensiones distintas", "La desviación de entalpía y la entropía relativa son familias de trazos diferentes; ninguna sustituye a la otra.", "El código de FrioCalc muestra Δh bajo una convención y s* de gas ideal con referencias elegidas.", "Activar/desactivar cada familia por separado y observar etiquetas/unidades; no atribuir s* a una carta ASHRAE convencional.", "Δh=h(Tbs,W)−h_sat(Tbh); s* compara estados del gas ideal contra referencia T*,p*.", "Localizar etiquetas de Δh y s*; comprobar su independencia de HR y del transportador FCS.", "Las referencias de s* son convencionales, no valores absolutos de aire real.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; https://coolprop.org/fluid_properties/HumidAir.html", ""),
        new TheoryTopic("BASE-11", "Carta", 0, 0, "Presión absoluta y cambio de unidades", "Las propiedades saturadas cambian con la presión; cada carta representa una P absoluta fija.", "El cálculo termodinámico se realiza en SI internamente y las etiquetas IP deben convertir sin alterar el estado.", "Comprobar la P indicada arriba y el tipo de carta estándar/personalizada antes de ubicar puntos.", "P abs≠P manométrica; T_F=1,8·T_C+32; 1 kPa≈0,145038 psi.", "Elegir presión conocida/altitud aproximada; aplicar; recalcular estados; cambiar unidades de presentación.", "La presión atmosférica estándar estimada por altitud no sustituye una lectura barométrica real.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", ""),
        new TheoryTopic("BASE-12", "Carta", 0, 0, "Método de resolución y trazado de procesos", "Dos variables independientes de estado y una presión determinan un punto; datos redundantes deben ser compatibles.", "Un proceso necesita estados, trayectoria o modelo de equipo; una mezcla necesita además caudales másicos.", "Seleccionar puntos en orden, verificar unidades, identificar T/W constantes o cambiantes, cerrar ciclos solo cuando corresponda.", "Σṁda,entrada=Σṁda,salida; Σṁda·W; Σṁda·h + Q̇ y aportes de agua.", "1) Entradas. 2) Resolver estados. 3) Validar saturación. 4) Seleccionar orden. 5) Balance masa/agua/energía. 6) Interpretar.", "Rutas geométricas no son automáticamente ciclos termodinámicos cerrados; no calcular potencias sin caudal.", "ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals; PsychroLib: https://psychrometrics.github.io/psychrolib/api_docs.html", "Mixing"),
        new TheoryTopic("A03-01", "A03", 1, 2, "Presentación e introducción", "La psicrometría estudia propiedades y procesos del aire húmedo, fundamento del acondicionamiento y de la refrigeración.", "Controlar solo Tbs no equivale a controlar humedad ni cargas latentes.", "Primero se reconoce el estado inicial y luego se sigue el proceso hacia el estado final.", "Variables base: Tbs, Tbh, HR, W, h, v y P.", "Distinguir propiedad de estado, transformación y capacidad de equipo.", "Diapositivas introductorias, no un diseño numérico completo.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", ""),
        new TheoryTopic("A03-02", "A03", 3, 5, "Calefacción y enfriamiento sensible", "La clase define calentamiento/enfriamiento sensible como cambios de Tbs sin variar W ni el punto de rocío.", "En calefacción a W constante, HR disminuye; en enfriamiento aumenta hasta rocío.", "Movimiento horizontal sobre la carta; el signo de Δh depende del sentido.", "W2=W1; h2−h1≈(1,006+1,86·W)·(T2−T1).", "Graficar estado inicial y final, conservar W, verificar que no se sobrepasa saturación.", "Si se cruza el rocío deja de ser únicamente sensible.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado); ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals", "Heating"),
        new TheoryTopic("A03-03", "A03", 6, 6, "Ejercicio 6: enfriar 5 m³/s", "Enfriar aire de 35 °C a 25 °C con W=10 g/kgda y V̇=5 m³/s.", "El caudal volumétrico se transforma a flujo másico usando v de entrada.", "Segmento horizontal a W=10 g/kgda desde 35 a 25 °C.", "ṁda=5/v1; Q̇=ṁda(h2−h1).", "1) Calcular v1. 2) Obtener h1 y h2. 3) ṁda=5/v1. 4) Signo de Q̇ es negativo en enfriamiento.", "P debe declararse; el ejercicio no suministra presión de estación.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", "Cooling"),
        new TheoryTopic("A03-04", "A03", 7, 7, "Ejercicio 7: precalentamiento", "Aire exterior 2 °C y 80% HR, caudal de 10000 m³/h; precalentar a 21 °C.", "La calefacción conserva W y aumenta h, aunque HR desciende.", "Desde Tbs=2 °C hacia Tbs=21 °C a la misma W.", "ṁda=(10000/3600)/v1; Q̇=ṁda·(h2−h1).", "Calcular W1 con Tbs y HR, luego v1, h1, h2 y potencia.", "El caudal es volumétrico de entrada; no usar v de salida sin convertir.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", "Heating"),
        new TheoryTopic("A03-05", "A03", 8, 9, "Introducción a humidificación y deshumidificación", "La presentación introduce la necesidad de controlar vapor para confort humano y procesos industriales.", "Humidificar agrega vapor; deshumidificar retira vapor; la HR puede cambiar también solo por T.", "Una trayectoria de humidificación suele subir en W; una de secado baja.", "ṁagua/ṁda=W2−W1 (signo de adición positivo).", "Comparar W1 y W2 y señalar el mecanismo de adición o eliminación.", "El confort y la selección de equipo no se deducen solo de W.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", "Steam"),
        new TheoryTopic("A03-06", "A03", 10, 13, "Métodos de humidificación, evaporación y desecantes", "La presentación repite esquemas de humidificación por vapor o evaporación y deshumidificación por enfriamiento o desecante.", "La adición evaporativa enfría idealmente; el vapor inyectado añade masa y entalpía; el desecante necesita propiedades propias.", "Comparar dirección de W y h según mecanismo, evitando una sola flecha universal.", "Vapor: W2=W1+ΔW, h2=h1+ΔW·h_vapor; evaporativo: T2≈T1−ε(T1−Tbh1).", "Seleccionar el proceso que coincida con el equipo físico; identificar los datos que faltan.", "Las figuras originales son principalmente visuales; las fórmulas aquí son explicación complementaria, no transcripción textual literal.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado); ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals", "Evaporative"),
        new TheoryTopic("A03-07", "A03", 14, 14, "Ejercicio 14: lavador con efectividad 70%", "Se recibe aire a 30 °C, 10% HR; el material denomina «rendimiento de Hendrickson» al 70%.", "El modelo docente de efectividad aproxima Tbs hacia Tbh e incrementa W.", "Se desplaza hacia aire más húmedo y más frío, dentro de la saturación.", "T2=T1−0,70·(T1−Tbh1); W2=W1+0,70[W_sat(Tbh1)−W1].", "Calcular Tbh1, luego T2 y W2, comparar HR2 con 95%.", "El nombre «Hendrickson» no queda confirmado como nomenclatura normativa de ASHRAE.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", "Evaporative"),
        new TheoryTopic("A03-08", "A03", 15, 15, "Ejercicio 15: condensación y calor latente", "El aire entra a Tbs=32 °C y Trocío=28 °C, sale a 21 °C con 100% HR.", "Eliminación de humedad = W1−W2; la carga del aire y del equipo no son siempre idénticas.", "Enfriar hasta rocío, luego seguir saturación hacia menor T y W.", "m_cond/m_da=W1−W2; Δh_aire=h1−h2; Q_serpentín≈ṁda(h1−h2)−ṁcond·h_l.", "Identificar punto de rocío, W1, W2, condensado y cambios sensible/latente con convención indicada.", "Separación latente simple ΔW·2501 es una aproximación, no una identidad exacta universal.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado); ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals", "Dehumidification"),
        new TheoryTopic("A03-09", "A03", 16, 17, "Procesos combinados: orden y estados", "El material presenta enfriamiento + deshumidificación; calentamiento + humidificación; mezcla adiabática.", "Cada etapa altera propiedades distintas y los estados intermedios importan en los balances.", "Dibujar P1→P_intermedio→P2, o dos entradas convergentes en mezcla.", "Para cada tramo aplicar conservación de ṁda, vapor y energía según entradas/salidas.", "Separar serpentín, evaporación, inyección, mezcla y recalentamiento.", "No confundir un proceso secuencial de dos tramos con la mezcla de dos entradas.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", "HeatingHumidification"),
        new TheoryTopic("A03-10", "A03", 18, 21, "Diagramas de procesos combinados", "Las diapositivas 18–21 son fundamentalmente esquemas comparativos de enfriamiento/deshumidificación, calefacción/humidificación y mezcla.", "Los trazos deben interpretarse como procesos condicionados por la masa de agua y la transferencia de calor.", "En condensación: primero W constante hasta rocío y luego W decrece; en mezcla: nodo de dos entradas.", "W2=W1−m_agua,ṁ/ṁda; h3=Σṁi·hi/Σṁi.", "Inspeccionar cada tramo y comprobar si se conserva W, h o ambas de modo aproximado.", "Las diapositivas incluyen imágenes sin texto de ecuaciones; se ofrece interpretación técnica sin afirmar detalles gráficos no verificados.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado); ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals", "Mixing"),
        new TheoryTopic("A03-11", "A03", 22, 22, "Ejercicio 22: auditorio y ventilación", "300 personas con 8 L/s por persona, interior 24 °C/55% HR y exterior 32 °C/68% HR; se solicita carga total.", "La ventilación aportada es 2,4 m³/s, pero no incluye todas las ganancias ni infiltraciones.", "Localizar condiciones exterior/interior y determinar diferencias de W y h.", "V̇aire exterior=300·8/1000=2,4 m³/s; ṁda=V̇/v_ext.", "Calcular la componente de acondicionamiento del aire exterior; pedir envolvente, personas, iluminación, equipos y régimen para total.", "No presentar la carga de ventilación como carga total del auditorio.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", "Mixing"),
        new TheoryTopic("A03-12", "A03", 23, 23, "Ejercicio 23: mezcla de retorno y exterior", "Mezcla 3000 m³/h de retorno (24 °C/55%) y 500 m³/h exterior (32 °C/70%).", "El volumen específico de cada corriente varía; el promedio correcto pondera por masa de aire seco.", "Unir entradas y ubicar mezcla sobre la línea ideal entre ambos estados (sin condensación).", "ṁ1=3000/(3600·v1); ṁ2=500/(3600·v2); W3=Σṁi·Wi/Σṁi; h3=Σṁi·hi/Σṁi.", "Calcular v1, v2, ṁ1, ṁ2, W3, h3 y Tbs3.", "No promediar temperaturas ni caudales volumétricos sin criterio de masa.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado)", "Mixing"),
        new TheoryTopic("A03-13", "A03", 24, 24, "Ejercicio 24: FCS interior y BF", "Auditorio con FCSi=0,75 y BF=0,20, mismas condiciones que el 22; se pide línea de impulsión y viabilidad del equipo.", "FCS orienta una pendiente de carga; BF modela aproximación a ADP. No definen punto único sin otros datos.", "Marcar local y líneas guía, pero no publicar punto de impulsión ficticio.", "FCS=Q_sensible/Q_total; h2=BF·h1+(1−BF)·hADP.", "Enumerar datos adicionales: cargas, caudal y ADP/serpentín.", "La combinación de dos factores por sí sola no garantiza capacidad ni condiciones de impulsión.", "A03 Procesos Psicrométricos(2).pptx, PhD Hermes Ramírez León (material aportado); ASHRAE Handbook—Fundamentals 2025, capítulo 1 (Psicrometría); https://www.ashrae.org/technical-resources/publications-library/ashrae-handbook/table-of-contents-2025-ashrae-handbook-fundamentals", "SHR"),
