    public static TheoryTopic? Find(string id) => Topics.FirstOrDefault(t=>t.Id==id);

    // La cobertura debe ser explícita: hay 36 diapositivas, no solo 24.
    public static IReadOnlyList<int> CoveredSlides => Topics
        .Where(t=>t.Group=="A03")
        .SelectMany(t=>Enumerable.Range(t.FirstSlide,t.LastSlide-t.FirstSlide+1))
        .OrderBy(x=>x).ToArray();

    public static TheoryTopic? ForSlide(int slide) => Topics.FirstOrDefault(t=>
        t.Group=="A03" && slide>=t.FirstSlide && slide<=t.LastSlide);

    public static string DetailedReading(TheoryTopic topic)
    {
        return $"{topic.SlideLabel}\n"+
            $"TEMA: {topic.Title}\n\n"+
            $"Resumen: {topic.Summary}\n\n"+
            $"Fundamento físico: {topic.PhysicalExplanation}\n\n"+
            $"Cómo se lee o representa en la carta: {topic.ChartReading}\n\n"+
            $"Ecuación o balance: {topic.Equation}\n\n"+
            $"Procedimiento de estudio: {topic.Procedure}\n\n"+
            $"Límites y datos faltantes: {topic.Limits}\n\n"+
            $"Procedencia: {topic.Source}";
    }
}
